import 'dotenv/config'
import express from 'express'
import cors from 'cors'
import { pool } from './db.js'

const app = express()
const port = Number(process.env.PORT ?? 3000)

// The preview origin is http://127.0.0.1:<port>; allow a list when one is set.
const allowedOrigins = process.env.CORS_ORIGIN
  ?.split(',')
  .map((origin) => origin.trim())
  .filter(Boolean)

app.use(cors({ origin: allowedOrigins && allowedOrigins.length > 0 ? allowedOrigins : true }))
app.use(express.json())

app.get('/api/health', async (_req, res) => {
  try {
    await pool.query('select 1')
    res.json({ ok: true })
  } catch (error) {
    res.status(500).json({ ok: false, error: error.message })
  }
})

app.get('/api/notes', async (_req, res, next) => {
  try {
    const { rows } = await pool.query(
      'select id, title, body, created_at from notes order by created_at desc limit 100',
    )
    res.json(rows)
  } catch (error) {
    next(error)
  }
})

app.post('/api/notes', async (req, res, next) => {
  const { title, body } = req.body ?? {}
  if (typeof title !== 'string' || title.trim() === '') {
    res.status(400).json({ error: 'title is required' })
    return
  }
  try {
    const { rows } = await pool.query(
      'insert into notes (title, body) values ($1, $2) returning id, title, body, created_at',
      [title.trim(), typeof body === 'string' ? body : ''],
    )
    res.status(201).json(rows[0])
  } catch (error) {
    next(error)
  }
})

app.use((error, _req, res, _next) => {
  console.error(error)
  res.status(500).json({ error: 'internal error' })
})

app.listen(port, '0.0.0.0', () => {
  console.log(`API listening on http://127.0.0.1:${port}`)
})

import pg from 'pg'

const { Pool } = pg
const connectionString = process.env.DATABASE_URL

// Hosted providers (Supabase, Neon) present their own certificate chain.
// rejectUnauthorized: false keeps a pooled endpoint working; pin a CA instead
// once you run your own Postgres.
const remote = Boolean(connectionString) && !/localhost|127\.0\.0\.1/.test(connectionString ?? '')

export const pool = new Pool({
  connectionString,
  ssl: remote ? { rejectUnauthorized: false } : undefined,
})

create table if not exists notes (
  id bigserial primary key,
  title text not null,
  body text not null default '',
  created_at timestamptz not null default now()
);
